import {address,colName,sheetRole,classify} from './engine.mjs';
const MAX_COMPRESSED=20*1024*1024,MAX_EXPANDED=100*1024*1024;
function validateZip(buffer){const v=new DataView(buffer);let total=0,count=0;for(let i=0;i<=v.byteLength-46;i++){if(v.getUint32(i,true)!==0x02014b50)continue;const size=v.getUint32(i+24,true),name=v.getUint16(i+28,true),extra=v.getUint16(i+30,true),comment=v.getUint16(i+32,true);total+=size;count++;if(total>MAX_EXPANDED||count>5000||size>40*1024*1024)throw Error('Workbook exceeds expanded size or archive entry limit.');i+=45+name+extra+comment;}if(!count)throw Error('The file is not a valid XLSX ZIP archive.');}
const elements=(node,name)=>Array.from(node.getElementsByTagNameNS('*',name));
const first=(node,name)=>elements(node,name)[0];
function xml(text){const d=new DOMParser().parseFromString(text,'application/xml');if(elements(d,'parsererror').length||/<!DOCTYPE|<!ENTITY/i.test(text))throw Error('Invalid or unsupported workbook XML.');return d;}
const fullText=n=>elements(n,'t').map(t=>t.textContent).join('');
function resolvePath(base,target){if(target.startsWith('/'))return target.slice(1);let parts=base.split('/').slice(0,-1);for(const p of target.split('/'))if(p==='..')parts.pop();else if(p!=='.')parts.push(p);return parts.join('/');}
function translate(f,from,to){const a=address(from),b=address(to);return f.replace(/"(?:[^"]|"")*"|(?:'((?:[^']|'')+)'!|([A-Za-z_][\w. ]*)!)?(\$?)([A-Z]{1,3})(\$?)(\d+)/g,(whole,s1,s2,ac,c,ar,r)=>{if(whole.startsWith('"'))return whole;const n=address(c+r);let col=ac?n.col:n.col+b.col-a.col,row=ar?+r:+r+b.row-a.row;if(col<1||row<1)return '#REF!';return `${s1?`'${s1}'!`:s2?s2+'!':''}${ac}${colName(col)}${ar}${row}`;});}
export async function readWorkbook(file,onProgress=()=>{}){
 if(!/\.xlsx$/i.test(file.name))throw Error('Choose an .xlsx workbook. Macro-enabled and legacy formats are not supported.');if(file.size>MAX_COMPRESSED)throw Error('Each workbook must be 20 MB or smaller.');const buffer=await file.arrayBuffer();validateZip(buffer);const zip=await globalThis.JSZip.loadAsync(buffer,{checkCRC32:false});let expanded=0;
 const read=async path=>{let f=zip.file(path);if(!f)return null;let data=await f.async('uint8array');expanded+=data.length;if(expanded>MAX_EXPANDED)throw Error('Expanded workbook exceeds 100 MB.');return xml(new TextDecoder().decode(data));};
 const wb=await read('xl/workbook.xml'),rels=await read('xl/_rels/workbook.xml.rels');if(!wb||!rels)throw Error('Required XLSX workbook parts are missing.');
 const relationship=new Map(elements(rels,'Relationship').filter(x=>x.getAttribute('TargetMode')!=='External').map(x=>[x.getAttribute('Id'),resolvePath('xl/workbook.xml',x.getAttribute('Target'))]));
 const ss=await read('xl/sharedStrings.xml'),strings=ss?elements(ss,'si').map(fullText):[];const styles=await read('xl/styles.xml');const formats=new Map(styles?elements(styles,'numFmt').map(x=>[+x.getAttribute('numFmtId'),x.getAttribute('formatCode')]):[]);const xfs=styles?Array.from(first(styles,'cellXfs')?.children||[]).map(x=>+x.getAttribute('numFmtId')):[];
 const w={name:file.name,size:file.size,sheets:[],namedRanges:elements(wb,'definedName').map(n=>({name:n.getAttribute('name'),value:n.textContent})),externalLinks:Object.keys(zip.files).filter(n=>/^xl\/externalLinks\/externalLink\d+\.xml$/.test(n)).length,hash:Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',buffer))).map(x=>x.toString(16).padStart(2,'0')).join('')};
 const sheets=elements(wb,'sheet');let totalCells=0;for(const [index,s]of sheets.entries()){onProgress(`Reading ${file.name} · ${s.getAttribute('name')} (${index+1}/${sheets.length})`);const rid=s.getAttribute('r:id')||s.getAttributeNS('http://schemas.openxmlformats.org/officeDocument/2006/relationships','id');const path=relationship.get(rid);if(!path)throw Error('Sheet relationship is missing.');const d=await read(path);if(!d)throw Error('A worksheet is missing from the archive.');let cells={},shared=new Map(),pending=[],rows=0,cols=0;
 for(const c of elements(d,'c')){const a=c.getAttribute('r'),pos=address(a);if(!pos)continue;if(++totalCells>500000)throw Error('Workbook exceeds the 500,000-cell safety limit.');const f=first(c,'f'),value=first(c,'v')?.textContent,type=c.getAttribute('t'),style=+c.getAttribute('s');let v=value??null;if(type==='s')v=strings[+value]??null;else if(type==='inlineStr')v=fullText(c);else if(type==='b')v=value==='1';else if(value!==undefined&&type!=='str'&&type!=='e'&&Number.isFinite(+value))v=+value;let formula=f?.textContent?'='+f.textContent:null;
 if(f?.getAttribute('t')==='shared'){let si=f.getAttribute('si');if(formula)shared.set(si,{a,formula});else pending.push({a,si});}
 if(v!==null||f)cells[a]={v,f:formula,t:type==='e'?'e':formula?'f':type||'n',z:formats.get(xfs[style])||({9:'0%',10:'0.00%',14:'mm-dd-yy',22:'m/d/yy h:mm'}[xfs[style]])||'General'};rows=Math.max(rows,pos.row);cols=Math.max(cols,pos.col);
 }
 for(const p of pending){let base=shared.get(p.si);if(!base)throw Error('A shared formula has no base expression.');cells[p.a].f=translate(base.formula,base.a,p.a);cells[p.a].t='f';}
 const name=s.getAttribute('name');w.sheets.push({name,role:sheetRole(name,cells),state:s.getAttribute('state')||'visible',rows,cols,cells,merges:elements(d,'mergeCell').map(x=>x.getAttribute('ref')),validations:elements(d,'dataValidation').length,tables:elements(d,'tablePart').map(x=>x.getAttribute('r:id')),charts:elements(d,'drawing').length,conditionalFormats:elements(d,'conditionalFormatting').length});await new Promise(resolve=>setTimeout(resolve,0));
 }w.role=classify(w);return w;
}
const escape=s=>String(s??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replace(/[\x00-\x08\x0B\x0C\x0E-\x1F]/g,'');
export async function reportXlsx(result){
 const headers=['Issue ID','Severity','KPI','Category','Period','Sheet','Location','Issue','Reported','Expected','Difference','Rule','Root cause','Downstream impact','Recommendation','Occurrences'];
 const data=[headers,...result.issues.map(x=>[x.id,x.severity,x.kpi,x.type,x.period,x.sheet,x.location,x.issue,x.reported,x.expected,x.difference,x.rule,x.rootCause,x.impact.join('; '),x.recommendation,x.occurrences.length])];
 const summary=[['KPI Audit Engine','Management report'],['Workbook',result.name],['Date',result.at],['Scope',result.scope.join('; ')],['Validation score',result.qualityScore??'Not calculated'],['Coverage %',result.coveragePercent],['Verified checks',result.coverage.verified],['Failed checks',result.coverage.failed],['Blocked checks',result.coverage.blocked],['Score definition',result.scoreDefinition],['Limitations',result.limitations.join('; ')]];
 const rows=table=>table.map((row,i)=>`<row r="${i+1}">${row.map((v,j)=>`<c r="${colName(j+1)}${i+1}" t="inlineStr"><is><t xml:space="preserve">${escape(v)}</t></is></c>`).join('')}</row>`).join('');
 const sheet=table=>`<?xml version="1.0" encoding="UTF-8"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetViews><sheetView workbookViewId="0"><pane ySplit="1" topLeftCell="A2" activePane="bottomLeft" state="frozen"/></sheetView></sheetViews><cols><col min="1" max="16" width="24" customWidth="1"/></cols><sheetData>${rows(table)}</sheetData><autoFilter ref="A1:${colName(table[0].length)}${table.length}"/></worksheet>`;
 const zip=new globalThis.JSZip();zip.file('[Content_Types].xml','<?xml version="1.0"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/><Override PartName="/xl/worksheets/sheet2.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/></Types>');
 zip.file('_rels/.rels','<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>');zip.file('xl/workbook.xml','<?xml version="1.0"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="Executive Summary" sheetId="1" r:id="rId1"/><sheet name="Audit Findings" sheetId="2" r:id="rId2"/></sheets></workbook>');zip.file('xl/_rels/workbook.xml.rels','<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/><Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet2.xml"/></Relationships>');zip.file('xl/worksheets/sheet1.xml',sheet(summary));zip.file('xl/worksheets/sheet2.xml',sheet(data));return zip.generateAsync({type:'blob',compression:'DEFLATE'});
}
